import{_ as e,H as l,f as r,i as s}from"./chunks/framework.DLd0CbzH.js";const x=JSON.parse('{"title":"Глоссарий — Agelto","description":"","frontmatter":{"type":"glossary","tags":["agelto","glossary"],"created":"2026-05-31T00:00:00.000Z","updated":"2026-06-14T00:00:00.000Z"},"headers":[],"relativePath":"02_Workflow/Glossary (Agelto).md","filePath":"02_Workflow/Glossary (Agelto).md"}'),n={name:"02_Workflow/Glossary (Agelto).md"};function g(d,t,a,o,i,f){return l(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="глоссарии-—-agelto" tabindex="-1">Глоссарий — Agelto <a class="header-anchor" href="#глоссарии-—-agelto" aria-label="Permalink to &quot;Глоссарий — Agelto&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Термин</th><th style="text-align:left;">Определение</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>ЕИС</strong></td><td style="text-align:left;">Единая информационная система в сфере закупок (zakupki.gov.ru) — основной источник данных</td></tr><tr><td style="text-align:left;"><strong>Смета</strong></td><td style="text-align:left;">Строительно-сметный расчет — документ с перечнем материалов, объемов и цен</td></tr><tr><td style="text-align:left;"><strong>Лот</strong></td><td style="text-align:left;">Часть заказа (тендера), может содержать несколько объектов закупки</td></tr><tr><td style="text-align:left;"><strong>Извещение</strong></td><td style="text-align:left;">Уведомление о закупке в ЕИС, имеет уникальный reg_number</td></tr><tr><td style="text-align:left;"><strong>Кроулер</strong></td><td style="text-align:left;">Автоматизированный агент для обхода страниц ЕИС и загрузки документов</td></tr><tr><td style="text-align:left;"><strong>Парсинг</strong></td><td style="text-align:left;">Извлечение структурированных данных из неструктурированных документов (PDF/Excel)</td></tr><tr><td style="text-align:left;"><strong>Матчинг</strong></td><td style="text-align:left;">Семантическое сопоставление позиции из сметы с позицией из каталога поставщика</td></tr><tr><td style="text-align:left;"><strong>Коллекция</strong></td><td style="text-align:left;">Номенклатурный каталог поставщика (его прайс-лист), загруженный в Agelto</td></tr><tr><td style="text-align:left;"><strong>Лид</strong></td><td style="text-align:left;">Верифицированная позиция из сметы, совпадающая с продукцией поставщика</td></tr><tr><td style="text-align:left;"><strong>Match Score</strong></td><td style="text-align:left;">Процент семантического совпадения позиции сметы с номенклатурой клиента</td></tr><tr><td style="text-align:left;"><strong>КТРУ</strong></td><td style="text-align:left;">Каталог товаров, работ, услуг для нужд государственных и муниципальных закупок</td></tr><tr><td style="text-align:left;"><strong>КСР</strong></td><td style="text-align:left;">Классификатор строительных ресурсов</td></tr><tr><td style="text-align:left;"><strong>ОКПД2</strong></td><td style="text-align:left;">Общероссийский классификатор продукции по видам экономической деятельности</td></tr><tr><td style="text-align:left;"><strong>ОКВЭД</strong></td><td style="text-align:left;">Общероссийский классификатор видов экономической деятельности</td></tr><tr><td style="text-align:left;"><strong>44-ФЗ</strong></td><td style="text-align:left;">ФЗ о контрактной системе (государственные закупки)</td></tr><tr><td style="text-align:left;"><strong>223-ФЗ</strong></td><td style="text-align:left;">ФЗ о закупках госкорпораций и субъектов естественных монополий</td></tr><tr><td style="text-align:left;"><strong>pgvector</strong></td><td style="text-align:left;">PostgreSQL-расширение для хранения и поиска векторных эмбеддингов</td></tr><tr><td style="text-align:left;"><strong>MDM</strong></td><td style="text-align:left;">Master Data Management — мастер-каталог строительных ресурсов Agelto</td></tr><tr><td style="text-align:left;"><strong>OCR</strong></td><td style="text-align:left;">Optical Character Recognition — распознавание текста в сканированных документах</td></tr><tr><td style="text-align:left;"><strong>NLP</strong></td><td style="text-align:left;">Natural Language Processing — обработка естественного языка</td></tr><tr><td style="text-align:left;"><strong>LayoutLM</strong></td><td style="text-align:left;">Трансформер-модель для понимания структуры документов (таблицы, координаты)</td></tr><tr><td style="text-align:left;"><strong>ICP</strong></td><td style="text-align:left;">Ideal Customer Profile — профиль идеального клиента</td></tr><tr><td style="text-align:left;"><strong>ARPU</strong></td><td style="text-align:left;">Average Revenue Per User — средняя выручка с клиента в год</td></tr><tr><td style="text-align:left;"><strong>CAC</strong></td><td style="text-align:left;">Customer Acquisition Cost — стоимость привлечения клиента</td></tr><tr><td style="text-align:left;"><strong>LTV</strong></td><td style="text-align:left;">Lifetime Value — суммарная выручка от клиента за весь срок жизни</td></tr><tr><td style="text-align:left;"><strong>MQL</strong></td><td style="text-align:left;">Marketing Qualified Lead — квалифицированный маркетинговый лид</td></tr><tr><td style="text-align:left;"><strong>SQL</strong></td><td style="text-align:left;">Sales Qualified Lead — лид, готовый к продаже</td></tr><tr><td style="text-align:left;"><strong>ЛПР</strong></td><td style="text-align:left;">Лицо, принимающее решение — коммерческий директор, РОП, CDO</td></tr><tr><td style="text-align:left;"><strong>ЖБИ</strong></td><td style="text-align:left;">Железобетонные изделия — один из приоритетных сегментов ICP</td></tr><tr><td style="text-align:left;"><strong>Zero-Search</strong></td><td style="text-align:left;">Концепция Agelto: менеджеру не нужно вводить запросы — система ищет сама</td></tr><tr><td style="text-align:left;"><strong>Deep Parsing Pipeline</strong></td><td style="text-align:left;">Конвейер глубокого парсинга: загрузка → OCR/AI → извлечение → нормализация</td></tr><tr><td style="text-align:left;"><strong>Fingerprint</strong></td><td style="text-align:left;">Хеш файла для отслеживания изменений: md5(имя + размер + дата изменения)</td></tr><tr><td style="text-align:left;"><strong>DocumentAnalysis</strong></td><td style="text-align:left;">Сущность Platform-модуля: задание на AI-анализ документа</td></tr><tr><td style="text-align:left;"><strong>PromptRule</strong></td><td style="text-align:left;">Настраиваемое правило для AI-запроса (шаг, контент, версия, приоритет)</td></tr><tr><td style="text-align:left;"><strong>Platform</strong></td><td style="text-align:left;">Ключевой модуль системы: кроулеры, парсинг, AI-анализ, прокси</td></tr><tr><td style="text-align:left;"><strong>Eis</strong></td><td style="text-align:left;">Модуль интеграции с zakupki.gov.ru</td></tr><tr><td style="text-align:left;"><strong>Sys</strong></td><td style="text-align:left;">Инфраструктурный модуль: прокси-пул, логирование</td></tr><tr><td style="text-align:left;"><strong>НМЦК</strong></td><td style="text-align:left;">Начальная (максимальная) цена контракта</td></tr><tr><td style="text-align:left;"><strong>ЛСР</strong></td><td style="text-align:left;">Локальный сметный расчёт — форма строительной сметы</td></tr><tr><td style="text-align:left;"><strong>Reg_number</strong></td><td style="text-align:left;">Уникальный реестровый номер закупки в ЕИС (ключ дедупликации)</td></tr><tr><td style="text-align:left;"><strong>Победитель</strong></td><td style="text-align:left;">Участник, определённый в протоколе подведения итогов; фактический покупатель материалов по смете (см. [[Procurement_Lifecycle]])</td></tr><tr><td style="text-align:left;"><strong>Протокол подведения итогов</strong></td><td style="text-align:left;">Официальный документ ЕИС с результатом закупки и победителем (ИНН, итоговая цена, дата)</td></tr><tr><td style="text-align:left;"><strong>Уклонение</strong></td><td style="text-align:left;">Победитель не подписал контракт в срок; публикуется «протокол об уклонении» → контракт со 2-м участником</td></tr><tr><td style="text-align:left;"><strong>Несостоявшаяся закупка</strong></td><td style="text-align:left;">Не выполнены условия конкуренции (нет/мало заявок, все отклонены) → возможна повторная</td></tr><tr><td style="text-align:left;"><strong>Единственный поставщик</strong></td><td style="text-align:left;">Неконкурентная закупка (ст.93 44-ФЗ); победитель известен заранее</td></tr><tr><td style="text-align:left;"><strong>Реестр контрактов</strong></td><td style="text-align:left;">Раздел ЕИС с заключёнными контрактами и сведениями об их исполнении/расторжении</td></tr><tr><td style="text-align:left;"><strong>РНП</strong></td><td style="text-align:left;">Реестр недобросовестных поставщиков</td></tr><tr><td style="text-align:left;"><strong>ЕРУЗ</strong></td><td style="text-align:left;">Единый реестр участников закупок</td></tr><tr><td style="text-align:left;"><strong>ФАС</strong></td><td style="text-align:left;">Федеральная антимонопольная служба — рассматривает жалобы по закупкам</td></tr></tbody></table>',2)])])}const _=e(n,[["render",g]]);export{x as __pageData,_ as default};
